/* Concentration only. Supabase timestamps are authoritative; the screen merely projects them. */
(()=>{
 const D=window.FocusData;
 const defaults={work:25,break:5,cycles:4,dailyHours:4,streakMinutes:30,sound:true,subjectId:'',chapterId:'',goal:'',notes:'',preset:'pomodoro',projectId:'',taskId:'',eventId:''};
 let api=null,user=null,rows=[],settings={...defaults},active=null,ready=false,loading=false,busy=false,error='',offset=0,generation=0,immersive=false,historyRange='week',historySubject='',historyChapter='',historyStart=todayISO(),historyEnd=todayISO(),historyLimit=20,pendingStart=null,lastPoll=0,transitioning=false,breakSkipped=false,lastSettleAttempt=0;
 const now=()=>Date.now()+offset;
 const escAttr=esc;
 const safeSettings=s=>({...defaults,...s,work:Math.max(1,Math.min(180,Number(s.work)||25)),break:Math.max(1,Math.min(60,Number(s.break)||5)),cycles:Math.max(1,Math.min(12,Number(s.cycles)||1)),dailyHours:Math.max(.5,Math.min(16,Number(s.dailyHours)||4)),streakMinutes:Math.max(1,Math.min(240,Number(s.streakMinutes)||30))});
 const isLive=r=>r&&!r.deleted_at&&['active','paused'].includes(r.status);
 const latest=()=>rows.filter(r=>!r.deleted_at&&!r.legacy_key).sort((a,b)=>Date.parse(b.started_at)-Date.parse(a.started_at))[0];
 function continuation(){const last=latest();if(active||breakSkipped||!last||last.kind!=='work'||last.status!=='completed'||D.iso(new Date(last.ended_at))!==todayISO()||now()-Date.parse(last.ended_at)>1800000||Date.parse(last.ended_at)>now())return null;return last}
 function nextWorkPrevious(){const r=latest();return !breakSkipped&&r?.kind==='break'&&r.cycle_index<r.cycles&&now()-Date.parse(r.ended_at)<1800000&&r.focus_duration===settings.work*60&&r.break_duration===settings.break*60&&r.cycles===settings.cycles&&(r.subject_id||'')===settings.subjectId&&(r.chapter_id||'')===settings.chapterId&&r.session_goal===settings.goal&&r.notes===settings.notes&&(r.project_id||'')===settings.projectId&&(r.task_id||'')===settings.taskId&&(r.event_id||'')===settings.eventId?r:null}
 function currentConfig(){const last=continuation();return active||last?{...settings,work:(active||last).focus_duration/60,break:(active||last).break_duration/60,cycles:(active||last).cycles,subjectId:(active||last).subject_id||'',chapterId:(active||last).chapter_id||'',goal:(active||last).session_goal,notes:(active||last).notes,projectId:(active||last).project_id||'',taskId:(active||last).task_id||'',eventId:(active||last).event_id||''}:settings}
 function applyMirror(){
  const before=JSON.stringify(state.focusSessions);
  state.focusSessions=rows.flatMap(r=>Object.entries(D.parts(r)).map(([date,seconds])=>({id:r.legacy_key||`focus:${r.id}:${date}`,source:'focus_v2',group:r.id,date,minutes:seconds/60,subject:r.subject_name,objective:r.session_goal,chapter:r.chapter_name,status:r.status,projectId:r.project_id||'',taskId:r.task_id||'',eventId:r.event_id||''})));
  state.focusSettings={...state.focusSettings,work:settings.work,break:settings.break,goal:settings.dailyHours,subject:state.subjects.find(s=>s.id===settings.subjectId)?.name||'',objective:settings.goal};
  focusRun={mode:active?.kind||'work',duration:active?(active.kind==='work'?active.focus_duration:active.break_duration):settings.work*60,left:active?Math.max(0,(active.kind==='work'?active.focus_duration:active.break_duration)-D.seconds(active,now())):settings.work*60,running:active?.status==='active',stamp:now(),segments:{},subject:active?.subject_name||'',objective:active?.session_goal||''};
  // Compatibility snapshot keeps existing dashboard/progression totals in sync.
  if(before!==JSON.stringify(state.focusSessions))save();
  window.dispatchEvent(new Event('prepago:study-changed'));
 }
 function updateResult(result){if(result.server_now)offset=Date.parse(result.server_now)-Date.now();if(result.session){const at=rows.findIndex(r=>r.id===result.session.id);if(at<0)rows.push(result.session);else rows[at]=result.session}active=rows.find(isLive)||null;applyMirror()}
 async function load(){
  if(!api||loading)return;loading=true;const gen=generation;
  try{const result=await api.load();if(gen!==generation)return;rows=result.rows;settings=safeSettings(result.config||{});if(result.server_now)offset=Date.parse(result.server_now)-Date.now();active=rows.find(isLive)||null;ready=true;error='';applyMirror();if(currentPage==='focus')renderFocus();await settle()}catch(e){if(gen===generation){error='Impossible de charger tes sessions. Vérifie ta connexion puis réessaie.';if(currentPage==='focus')renderFocus()}}finally{if(gen===generation)loading=false}
 }
 function makeAdapter(client,id){return {
  async load(){const boot=await client.rpc('study_bootstrap');if(boot.error)throw boot.error;const pref=await client.from('study_settings').select('config').eq('user_id',id).single();if(pref.error)throw pref.error;const all=[];for(let start=0;;start+=1000){const q=await client.from('study_sessions').select('*').eq('user_id',id).order('started_at',{ascending:false}).order('id').range(start,start+999);if(q.error)throw q.error;all.push(...q.data);if(q.data.length<1000)break}return {rows:all,config:pref.data.config,server_now:boot.data.server_now}},
  async action(action,row,payload){const q=await client.rpc('study_action',{p_action:action,p_id:row.id,p_revision:row.revision??null,p_payload:payload||{}});if(q.error)throw q.error;return q.data},
  async settings(config){const q=await client.from('study_settings').update({config,updated_at:new Date().toISOString()}).eq('user_id',id);if(q.error)throw q.error}
 }}
 async function persistSettings(){if(!api||!ready)throw Error('not_connected');const gen=generation;await api.settings(settings);if(gen!==generation)return;state.focusSettings.goal=settings.dailyHours;save()}
 async function act(action,row=active,payload){if(busy||!ready||!api)return false;busy=true;error='';refreshControls();const gen=generation;try{const result=await api.action(action,row,payload);if(gen!==generation)return false;updateResult(result);if(result.conflict)showToast('Session actualisée depuis un autre onglet.');else if(action==='finish')showToast('Temps étudié enregistré.');else if(action==='delete')showToast('Session retirée de ton historique.');return !result.conflict}catch(e){if(gen===generation){error='Action non enregistrée. Vérifie ta connexion puis réessaie. Le chrono reste basé sur la dernière confirmation.';showToast('Connexion nécessaire pour enregistrer cette action.')}return false}finally{if(gen===generation){busy=false;if(currentPage==='focus')renderFocus()}}}
 async function settle(){if(!active||active.status!=='active'||busy||transitioning||Date.now()-lastSettleAttempt<15000)return;const cap=active.kind==='work'?active.focus_duration:active.break_duration;if(D.seconds(active,now())<cap)return;transitioning=true;lastSettleAttempt=Date.now();const kind=active.kind;const ok=await act('settle');transitioning=false;if(ok){if(settings.sound){unlockFocusSound();focusChime()}showToast(kind==='work'?'Session terminée. Prends une pause.':'Pause terminée. Prêt pour la suite ?')}}
 function readForm(){const form=document.querySelector('#cockpitSetup');if(!form)return true;if(!form.reportValidity())return false;const d=Object.fromEntries(new FormData(form));settings=safeSettings({...settings,...d,sound:form.elements.sound.checked});return true}
 async function start(kind='work',previous=null){
  if(busy||!ready)return;const gen=generation;if(!previous&&!readForm())return;
  try{try{await window.PrepagoSync?.flush()}catch{await window.PrepagoSync?.flush()}await persistSettings()}catch{error='Réglages non enregistrés. Réessaie quand la connexion est rétablie.';renderFocus();return}
  if(gen!==generation)return;if(!state.tasks.some(t=>t.id===settings.taskId))settings.taskId='';if(!state.events.some(t=>t.id===settings.eventId))settings.eventId='';lastSettleAttempt=0;const payload=previous?{...settings,work:previous.focus_duration/60,break:previous.break_duration/60,cycles:previous.cycles,subjectId:previous.subject_id||'',chapterId:previous.chapter_id||'',goal:previous.session_goal,notes:previous.notes,projectId:previous.project_id||'',taskId:previous.task_id||'',eventId:previous.event_id||'',kind,cycleIndex:kind==='break'?previous.cycle_index:previous.cycle_index<previous.cycles?previous.cycle_index+1:1}:{...settings,kind,cycleIndex:1};
  pendingStart||={id:crypto.randomUUID?crypto.randomUUID(): '10000000-1000-4000-8000-100000000000'.replace(/[018]/g,c=>(Number(c)^crypto.getRandomValues(new Uint8Array(1))[0]&15>>Number(c)/4).toString(16))};unlockFocusSound();const ok=await act('start',pendingStart,payload);if(ok){pendingStart=null;breakSkipped=false}
 }
 async function deleteSession(id){const row=rows.find(r=>r.id===id);if(!row)return;openModal('Retirer cette session ?',`<p>Les statistiques seront recalculées. Cette session sera masquée, sans effacer les données historiques.</p>`,()=>{});const form=document.querySelector('#modalForm');form.querySelector('[type="submit"]').textContent='Retirer la session';form.onsubmit=async e=>{e.preventDefault();const ok=await act('delete',row);if(ok)closeModal()}}
 function range(){const today=todayISO();if(historyRange==='today')return [today,today];if(historyRange==='month')return [today.slice(0,8)+'01',today];if(historyRange==='custom')return [historyStart,historyEnd];return [D.monday(),today]}
 const subjectOptionsHtml=(value,all=false)=>`<option value="">${all?'Toutes les matières':'Étude libre'}</option>`+state.subjects.map(s=>`<option value="${esc(s.id)}" ${s.id===value?'selected':''}>${esc(s.name)}</option>`).join('');
 function chapterOptions(subject,value,all=false){return `<option value="">${all?'Tous les chapitres':'Sans chapitre'}</option>`+(state.subjects.find(s=>s.id===subject)?.chapters||[]).map(c=>`<option value="${esc(c.id)}" ${c.id===value?'selected':''}>${esc(c.name)}</option>`).join('')}
 function empty(){return `<div class="fc-empty">${uiIcon('focus')}<h3>Ton travail prend forme ici.</h3><p>Commence ta première session de concentration pour voir tes statistiques.</p><button class="secondary-btn" data-fc-action="jump">Démarrer une session</button></div>`}
 function todayCard(){const today=todayISO(),total=D.totals(rows,today,today),complete=total.rows.filter(r=>r.status==='completed').length,pct=Math.min(100,total.total/(settings.dailyHours*3600)*100);return `<section class="fc-card fc-today"><div class="fc-card-title"><h2>Aujourd’hui</h2><span class="fc-streak" title="Au moins ${settings.streakMinutes} min de sessions terminées par jour">🔥 ${D.streak(rows,settings.streakMinutes*60)} jours</span></div><div class="fc-today-number">${D.duration(total.total)}<span>étudiées</span></div><div class="fc-today-meta"><span>${complete} session${complete===1?'':'s'} terminée${complete===1?'':'s'}</span><strong>${Math.floor(pct)} %</strong></div><div class="fc-progress" role="progressbar" aria-label="Objectif quotidien" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.floor(pct)}"><span style="width:${pct}%"></span></div><button class="fc-text-button" data-fc-action="goal">Objectif : ${settings.dailyHours} h / jour ${uiIcon('right')}</button><p class="fc-caption">Temps enregistré, hors pauses. Série : ${settings.streakMinutes} min de sessions terminées / jour.</p></section>`}
 function analytics(){const start=D.monday(),week=D.dates(start,7),prev=D.dates(start,1).map(d=>{const x=new Date(d+'T12:00:00');x.setDate(x.getDate()-7);return D.iso(x)})[0],last=D.totals(rows,prev,D.dates(prev,7)[6]),stats=D.totals(rows,start,week[6]),max=Math.max(3600,...Object.values(stats.daily)),change=last.total?`${stats.total>=last.total?'+':''}${Math.round((stats.total-last.total)/last.total*100)} % vs semaine dernière`:stats.total?'Première semaine enregistrée':'Aucune session cette semaine';return `<div class="fc-analytics"><section class="fc-card"><div class="fc-card-title"><div><span class="fc-eyebrow">CETTE SEMAINE</span><h2>Ton rythme d’étude</h2></div><span class="fc-caption">${formatShort(start)} – ${formatShort(week[6])}</span></div>${stats.total?`<div class="fc-week-total"><strong>${D.duration(stats.total)}</strong><span>${change}</span></div><div class="fc-chart" aria-label="Temps étudié par jour">${week.map((date,i)=>{const sec=stats.daily[date]||0;return `<div class="fc-bar"><span class="fc-bar-value">${sec?D.duration(sec):'—'}</span><div class="fc-bar-track"><span style="height:${sec?Math.max(3,sec/max*100):0}%" class="${date===todayISO()?'today':''}" role="img" aria-label="${formatDate(new Date(date+'T12:00:00'))} : ${D.duration(sec)}"></span></div><span>${['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'][i]}</span></div>`}).join('')}</div>`:empty()}</section><section class="fc-card"><div class="fc-card-title"><div><span class="fc-eyebrow">CETTE SEMAINE</span><h2>Par matière</h2></div>${uiIcon('subjects')}</div>${stats.total?`<div class="fc-breakdown">${stats.subjects.map(s=>`<div><div class="fc-breakdown-label"><strong>${esc(s.name)}</strong><span>${D.duration(s.seconds)}</span></div><div class="fc-progress"><span style="width:${s.seconds/stats.total*100}%"></span></div></div>`).join('')}</div><p class="fc-caption">Répartition du temps enregistré cette semaine.</p>`:'<div class="fc-empty"><p>Choisis une matière avant de démarrer pour suivre ton temps de travail par discipline.</p></div>'}</section></div>`}
 function history(){const [from,to]=range(),stats=D.totals(rows,from,to,historySubject,historyChapter);const choices=[['today','Aujourd’hui'],['week','Cette semaine'],['month','Ce mois'],['custom','Dates personnalisées']];return `<section class="fc-card fc-history"><div class="fc-card-title"><div><span class="fc-eyebrow">HISTORIQUE</span><h2>Sessions récentes</h2></div><span class="fc-caption">Pauses exclues</span></div><div class="fc-history-filters"><select id="fcHistoryRange" aria-label="Période des sessions">${choices.map(([v,l])=>`<option value="${v}" ${v===historyRange?'selected':''}>${l}</option>`).join('')}</select><select id="fcHistorySubject" aria-label="Filtrer les sessions par matière">${subjectOptionsHtml(historySubject,true)}</select><select id="fcHistoryChapter" aria-label="Filtrer les sessions par chapitre" ${!historySubject?'disabled':''}>${chapterOptions(historySubject,historyChapter,true)}</select>${historyRange==='custom'?`<label>Du <input type="date" id="fcHistoryStart" value="${historyStart}" max="${historyEnd}"></label><label>Au <input type="date" id="fcHistoryEnd" value="${historyEnd}" min="${historyStart}"></label>`:''}</div><div class="fc-history-metrics">${[[D.duration(stats.total),'Temps total'],[D.duration(stats.average),'Durée moyenne'],[stats.count,'Sessions'],[D.duration(stats.longest),'Plus longue durée']].map(([v,l])=>`<div><strong>${v}</strong><span>${l}</span></div>`).join('')}</div>${stats.rows.length?`<div class="fc-session-list">${stats.rows.slice(0,historyLimit).map(r=>`<article class="fc-session"><span class="fc-session-symbol">${uiIcon('subjects')}</span><div class="fc-session-copy"><strong>${esc(r.subject_name||'Étude libre')}</strong><span>${esc(r.chapter_name||'Sans chapitre')}</span>${r.session_goal?`<p>${esc(r.session_goal)}</p>`:''}${r.notes?`<details><summary>Note de session</summary><p>${esc(r.notes)}</p></details>`:''}</div><div class="fc-session-time"><strong>${D.duration(r.duration_seconds)}</strong><span>${r.legacy_date?formatShort(r.legacy_date)+' · ancien historique':new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(r.started_at))}</span></div><span class="fc-status ${r.status}">${r.status==='completed'?'✓ Terminée':'Interrompue'}</span><button class="icon-btn" data-fc-delete="${esc(r.id)}" aria-label="Retirer la session de ${esc(r.subject_name||'travail')} du ${esc(r.legacy_date||r.started_at)}">${uiIcon('close')}</button></article>`).join('')}</div>${stats.count>historyLimit?'<button class="secondary-btn" data-fc-action="more">Afficher plus de sessions</button>':''}`:`<div class="fc-empty"><p>${rows.some(r=>Object.keys(D.parts(r)).length)?'Aucune session ne correspond à ces filtres.':'Commence ta première session de concentration pour voir tes statistiques.'}</p><button class="secondary-btn" data-fc-action="${rows.length?'reset-filters':'jump'}">${rows.length?'Réinitialiser les filtres':'Démarrer une session'}</button></div>`}<p class="fc-caption">Les totaux portent sur les dates sélectionnées. Une session à cheval sur deux jours est répartie entre ces jours.</p></section>`}
 function setup(){const c=currentConfig(),locked=!!active,disable=locked?'disabled':'',preset=c.preset||'custom';return `<section class="fc-card fc-setup"><div class="fc-card-title"><h2>Préparer ma session</h2><span class="fc-caption">${locked?'Session en cours':'À ton rythme'}</span></div><form id="cockpitSetup"><fieldset ${disable}><legend>Rythme de travail</legend><div class="fc-presets">${[['pomodoro','Pomodoro','25 / 5',25,5],['deep','Deep Work','50 / 10',50,10],['long','Focus long','90 / 15',90,15],['custom','Personnalisé','À ton rythme',0,0]].map(([v,l,n])=>`<button type="button" data-fc-preset="${v}" aria-pressed="${preset===v}" class="${preset===v?'selected':''}"><strong>${l}</strong><span>${n}</span></button>`).join('')}</div><div class="fc-duration-fields"><label>Étude (min)<input name="work" type="number" min="1" max="180" value="${c.work}" required></label><label>Pause (min)<input name="break" type="number" min="1" max="60" value="${c.break}" required></label><label>Cycles<input name="cycles" type="number" min="1" max="12" value="${c.cycles}" required></label></div><div class="fc-selector-grid"><label>Matière<select name="subjectId" id="fcSubject">${subjectOptionsHtml(c.subjectId)}</select></label><label>Chapitre<select name="chapterId" id="fcChapter">${chapterOptions(c.subjectId,c.chapterId)}</select></label></div>${window.PrepagoConnections?.focusFields(c)||''}<label>Objectif de cette session<input name="goal" maxlength="240" value="${esc(c.goal)}" placeholder="Ex. Finir les exercices 4–7"></label><details class="fc-note" ${c.notes?'open':''}><summary>Ajouter une note (facultatif)</summary><label>Note de session<textarea name="notes" maxlength="4000" rows="3" placeholder="Une méthode à tester, un point à revoir…">${esc(c.notes)}</textarea></label></details></fieldset><label class="fc-sound"><input name="sound" type="checkbox" ${c.sound?'checked':''}> Son en fin de session</label><button class="secondary-btn" type="submit" ${busy?'disabled':''}>Enregistrer les réglages</button><p class="fc-caption">${locked?'Matière et durées verrouillées pour cette session.':'Chaque cycle commence quand tu es prêt. Aucune session de travail ne démarre toute seule.'}</p></form></section>`}
 function timerCard(){const c=currentConfig(),last=continuation(),rest=active?.kind==='break'||!!last,status=active?.status,subject=active?.subject_name||last?.subject_name||state.subjects.find(s=>s.id===c.subjectId)?.name||'Étude libre',chapter=active?.chapter_name||last?.chapter_name||state.subjects.find(s=>s.id===c.subjectId)?.chapters.find(ch=>ch.id===c.chapterId)?.name||'',cycle=active?.cycle_index||last?.cycle_index||(nextWorkPrevious()?nextWorkPrevious().cycle_index+1:1);return `<section class="fc-card fc-timer ${rest?'is-break':''}"><div class="fc-timer-top"><span class="fc-mode">${rest?'TEMPS DE PAUSE':'CONCENTRATION'}</span><button class="fc-immersive" data-fc-action="immersive" aria-pressed="${immersive}">${immersive?'Quitter le mode concentration':'Mode concentration'} ${uiIcon(immersive?'close':'focus')}</button></div><div class="fc-session-context"><span>${esc(subject)}</span><h2>${esc(chapter|| (rest?'Souffle un peu.':'Un objectif à la fois.'))}</h2></div><div class="fc-clock-wrap"><div class="fc-clock" id="fcClock" role="timer" aria-label="Temps restant">${timeText(Math.ceil(active?Math.max(0,(rest?active.break_duration:active.focus_duration)-D.seconds(active,now())):(rest?c.break:c.work)*60))}</div><p id="fcTimerState">${status==='paused'?'Session en pause':status==='active'?'Session en cours':rest?'Session terminée · pause méritée':'Prêt à commencer'} · Cycle ${cycle} / ${c.cycles}</p><div class="fc-timer-track"><span id="fcTimerProgress"></span></div></div><div class="fc-timer-actions">${active?`<button class="primary-btn" data-fc-action="${status==='active'?'pause':'resume'}">${uiIcon(status==='active'?'pause':'play')}${status==='active'?'Pause':'Reprendre'}</button><button class="secondary-btn" data-fc-action="finish">${rest?'Passer la pause':'Terminer'}</button>`:last?`<button class="primary-btn" data-fc-action="break">${uiIcon('play')} Commencer la pause</button><button class="secondary-btn" data-fc-action="next">Passer la pause</button>`:`<button class="primary-btn" data-fc-action="start">${uiIcon('play')} ${nextWorkPrevious()?'Démarrer la session suivante':'Démarrer'}</button>`}</div><div class="fc-goal"><span>OBJECTIF DE CETTE SESSION</span><p id="fcVisibleGoal">${esc(c.goal||'Choisis un objectif, ou commence librement.')}</p>${c.notes?`<details><summary>Ma note</summary><p>${esc(c.notes)}</p></details>`:''}</div><p class="fc-caption fc-timer-foot">${rest?'Les pauses ne comptent pas dans ton temps d’étude.':'Le chrono continue si tu changes de page ou fermes cet onglet, jusqu’à la durée choisie.'}</p><p class="fc-announcement" role="status" id="fcAnnouncement"></p></section>`}
 renderFocus=function(){
  document.body.classList.toggle('focus-cockpit-immersive',immersive);document.querySelector('#page').innerHTML=`<div class="focus-cockpit"><header class="fc-heading"><div><span class="fc-eyebrow">TON ESPACE DE TRAVAIL</span><h1>Concentration</h1><p>Un chapitre. Un objectif. Du temps pour avancer.</p></div><span class="fc-connection">${busy?'Enregistrement…':ready?'Sessions synchronisées':'Connexion…'}</span></header>${error?`<div class="fc-error" role="alert">${esc(error)}<button class="secondary-btn" data-fc-action="retry">Réessayer</button></div>`:''}${!ready?`<section class="fc-card fc-loading" role="status"><h2>${error?'Tes données restent conservées.':'Chargement de ton espace…'}</h2><p>Connexion à tes sessions enregistrées.</p></section>`:`<div class="fc-workspace"><div class="fc-main-column">${timerCard()}${todayCard()}</div>${setup()}</div>${analytics()}${history()}`}</div>`;
  if(ready){document.querySelector('#cockpitSetup').onsubmit=async e=>{e.preventDefault();if(active){settings.sound=e.target.elements.sound.checked}else if(!readForm())return;try{await persistSettings();showToast('Réglages enregistrés');renderFocus()}catch{error='Impossible d’enregistrer les réglages.';renderFocus()}};tick();refreshControls()}
 };
 function refreshControls(){document.querySelectorAll('.focus-cockpit [data-fc-action]').forEach(b=>{if(!['immersive','jump','goal','more','reset-filters','retry'].includes(b.dataset.fcAction))b.disabled=busy||!ready})}
 function tick(){if(!ready)return;const clock=document.querySelector('#fcClock');if(clock&&active){const cap=active.kind==='work'?active.focus_duration:active.break_duration,elapsed=D.seconds(active,now());clock.textContent=timeText(Math.ceil(Math.max(0,cap-elapsed)));document.querySelector('#fcTimerProgress').style.width=Math.min(100,elapsed/cap*100)+'%'}if(active){focusRun.left=Math.max(0,(active.kind==='work'?active.focus_duration:active.break_duration)-D.seconds(active,now()));focusRun.running=active.status==='active'}settle()}
 function goalModal(){openModal('Mes objectifs d’étude',`<div class="field"><label for="dailyHours">Objectif quotidien (heures)</label><input id="dailyHours" name="dailyHours" type="number" min="0.5" max="16" step="0.5" value="${settings.dailyHours}" required></div><div class="field"><label for="streakMinutes">Minimum pour la série (min / jour)</label><input id="streakMinutes" name="streakMinutes" type="number" min="1" max="240" value="${settings.streakMinutes}" required></div><p>La série compte uniquement le temps des sessions terminées, jamais les pauses.</p>`,()=>{});document.querySelector('#modalForm').onsubmit=async e=>{e.preventDefault();const previous={...settings};settings=safeSettings({...settings,...Object.fromEntries(new FormData(e.target))});try{await persistSettings();closeModal();renderFocus();showToast('Objectifs enregistrés')}catch{settings=previous;showToast('Objectifs non enregistrés. Réessaie.')}}}
 document.addEventListener('click',async e=>{
  const preset=e.target.closest('[data-fc-preset]');if(preset&&!active){if(!readForm())return;const choice=preset.dataset.fcPreset;breakSkipped=true;settings.preset=choice;if(choice!=='custom'){const v={pomodoro:[25,5],deep:[50,10],long:[90,15]}[choice];settings.work=v[0];settings.break=v[1]}try{await persistSettings()}catch{error='Réglages non synchronisés.'}renderFocus();return}
  const del=e.target.closest('[data-fc-delete]');if(del){await deleteSession(del.dataset.fcDelete);return}
  const b=e.target.closest('[data-fc-action]');if(!b||b.disabled)return;const a=b.dataset.fcAction;
  if(a==='immersive'){immersive=!immersive;renderFocus();document.querySelector('[data-fc-action="immersive"]')?.focus()}
  if(a==='start'){await start('work',nextWorkPrevious())}
  if(a==='break')await start('break',continuation());
  if(a==='next'){const prev=continuation();breakSkipped=true;await start('work',prev)}
  if(a==='pause'||a==='resume'){unlockFocusSound();await act(a)}
  if(a==='finish'){const previous=active;await act('finish');if(previous?.kind==='break'){breakSkipped=false;renderFocus()}}
  if(a==='retry')await load();if(a==='goal')goalModal();if(a==='jump'){document.querySelector('.fc-timer')?.scrollIntoView({behavior:'smooth',block:'center'});document.querySelector('.fc-timer .primary-btn')?.focus()}
  if(a==='more'){historyLimit+=20;renderHistory()}
  if(a==='reset-filters'){historyRange='week';historySubject=historyChapter='';renderHistory()}
 });
 function renderHistory(){const node=document.querySelector('.fc-history');if(node)node.outerHTML=history()}
 document.addEventListener('change',async e=>{
  const id=e.target.id;if(id==='fcProject'){settings.taskId='';settings.eventId=''}
  if(id==='fcSubject'){document.querySelector('#fcChapter').innerHTML=chapterOptions(e.target.value,'');settings.subjectId=e.target.value;settings.chapterId=''}
  if(e.target.closest('#cockpitSetup')){if(!active&&readForm()){breakSkipped=true;if(['work','break'].includes(e.target.name))settings.preset='custom';try{await persistSettings()}catch{error='Réglages non synchronisés.'}const timer=document.querySelector('.fc-timer');if(timer)timer.outerHTML=timerCard();document.querySelectorAll('[data-fc-preset]').forEach(b=>{b.classList.toggle('selected',b.dataset.fcPreset===settings.preset);b.setAttribute('aria-pressed',b.dataset.fcPreset===settings.preset)})}else if(e.target.name==='sound'){settings.sound=e.target.checked;try{await persistSettings()}catch{showToast('Réglage audio non enregistré.')}}}
  if(id==='fcHistoryRange')historyRange=e.target.value;else if(id==='fcHistorySubject'){historySubject=e.target.value;historyChapter=''}else if(id==='fcHistoryChapter')historyChapter=e.target.value;else if(id==='fcHistoryStart')historyStart=e.target.value||todayISO();else if(id==='fcHistoryEnd')historyEnd=e.target.value||todayISO();else return;historyLimit=20;renderHistory();
 });
 document.addEventListener('input',e=>{if(e.target.name==='goal'&&e.target.closest('#cockpitSetup'))document.querySelector('#fcVisibleGoal').textContent=e.target.value||'Choisis un objectif, ou commence librement.'});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&immersive){immersive=false;renderFocus()}});
 const previousRender=render;render=function(){if(currentPage!=='focus'){immersive=false;document.body.classList.remove('focus-cockpit-immersive')}return previousRender()};
 // Retire the old accounting loop; keep its public display hooks safe for other pages.
 settleFocus=function(){};finishFocus=function(){if(active)act('finish')};updateFocusDisplay=function(){};persistFocus=function(){};
 prepareFocus=function(task){if(active){navigate('focus');showToast('Termine ou reprends ta session en cours.');return}settings={...settings,subjectId:state.subjects.find(s=>s.name===task.subject)?.id||'',chapterId:task.revisionChapter||task.chapterId||'',projectId:task.projectId||'',taskId:state.tasks.some(t=>t.id===task.id)?task.id:'',eventId:task.eventId||'',goal:task.title,work:Math.min(180,Math.max(1,Number(task.minutes)||settings.work)),preset:'custom'};navigate('focus');if(api&&ready)persistSettings().catch(()=>{})};
 window.PrepagoFocus={
  refreshMirror(){if(ready)applyMirror();},
  leaveImmersive(){immersive=false;document.body.classList.remove('focus-cockpit-immersive')},
  snapshot(){return structuredClone({rows,active,ready,settings})},
  async connect(client,id){if(user===id&&api)return;this.clear();user=id;api=makeAdapter(client,id);await load()},
  async connectAdapter(adapter,id){this.clear();user=id;api=adapter;await load()},
  clear(){generation++;api=null;user=null;rows=[];active=null;ready=false;loading=false;busy=false;error='';settings={...defaults};pendingStart=null;immersive=false;offset=0;historyRange='week';historySubject=historyChapter='';historyStart=historyEnd=todayISO();historyLimit=20;lastPoll=lastSettleAttempt=0;transitioning=breakSkipped=false;document.body.classList.remove('focus-cockpit-immersive')},
  async pauseForSignOut(){if(active?.status==='active')await act('pause')}
 };
 setInterval(()=>{tick();if(api&&ready&&!busy&&!loading&&!document.hidden&&Date.now()-lastPoll>15000){lastPoll=Date.now();const gen=generation;api.load().then(result=>{if(gen!==generation||busy)return;const changed=JSON.stringify(rows)!==JSON.stringify(result.rows);rows=result.rows;active=rows.find(isLive)||null;if(result.server_now)offset=Date.parse(result.server_now)-Date.now();if(changed){applyMirror();if(currentPage==='focus'&&!document.activeElement?.closest('#cockpitSetup'))renderFocus()}}).catch(()=>{})}},1000);
 document.addEventListener('visibilitychange',()=>{if(!document.hidden&&api&&!busy)load()});
})();
